// Společné bezpečné chování webu. Tento soubor nesmí měnit pořadí článků,
// titulní hero ani redakční texty.

// NASEKADAN_ARTICLE_STANDARD_RUNTIME_V2
(() => {
  'use strict';
  const install = () => {
    if (!document.querySelector('main.article-shell[data-article-template="unified-v1"]')) return;
    if (document.getElementById('nk-article-standard-runtime-v2')) return;
    const style = document.createElement('style');
    style.id = 'nk-article-standard-runtime-v2';
    style.textContent = `
      main.article-shell[data-article-template="unified-v1"]{display:grid!important;grid-template-columns:minmax(0,840px) 300px!important;gap:36px!important;align-items:start!important;padding:54px 0 72px!important}
      main.article-shell[data-article-template="unified-v1"]>.article{background:#fff!important;border:1px solid #e1e6e8!important;border-radius:26px!important;padding:38px 42px 48px!important;box-shadow:0 18px 44px #14232d18!important;min-width:0!important;box-sizing:border-box!important}
      main.article-shell[data-article-template="unified-v1"]>.article h1{font:900 clamp(40px,6vw,64px)/1.02 Georgia,serif!important;letter-spacing:-.04em!important;margin:.22em 0 .3em!important;color:#17242d!important}
      main.article-shell[data-article-template="unified-v1"]>.article h2{font:900 33px/1.16 Georgia,serif!important;margin:46px 0 15px!important;color:#17242d!important}
      main.article-shell[data-article-template="unified-v1"]>.article p,main.article-shell[data-article-template="unified-v1"]>.article li{font-size:18px;line-height:1.7}
      main.article-shell[data-article-template="unified-v1"]>.article .leadtext{font-size:23px!important;color:#465862!important;line-height:1.52!important}
      main.article-shell[data-article-template="unified-v1"]>aside.sticky{position:sticky!important;top:100px!important;min-width:0!important}
      main.article-shell[data-article-template="unified-v1"]>aside.sticky .sidebox{background:#fff!important;border:1px solid #dce3e6!important;border-radius:18px!important;padding:20px!important;margin-bottom:18px!important;box-shadow:0 10px 30px #16242d0d!important}
      main.article-shell[data-article-template="unified-v1"] .promo-card,main.article-shell[data-article-template="unified-v1"] .article-rail-card,main.article-shell[data-article-template="unified-v1"] .featured-rotating-ad,main.article-shell[data-article-template="unified-v1"] .featured-cleaning-ad{max-width:100%!important;box-sizing:border-box!important}
      main.article-shell[data-article-template="unified-v1"] .promo-card img,main.article-shell[data-article-template="unified-v1"] .article-rail-card img,main.article-shell[data-article-template="unified-v1"] .featured-rotating-ad img,main.article-shell[data-article-template="unified-v1"] .featured-cleaning-ad img{max-width:100%!important;height:auto!important}
      @media(max-width:980px){main.article-shell[data-article-template="unified-v1"]{grid-template-columns:1fr!important}main.article-shell[data-article-template="unified-v1"]>aside.sticky{position:static!important}}
      @media(max-width:700px){main.article-shell[data-article-template="unified-v1"]{padding:28px 0 48px!important}main.article-shell[data-article-template="unified-v1"]>.article{padding:27px 21px 34px!important;border-radius:20px!important}main.article-shell[data-article-template="unified-v1"]>.article h1{font-size:42px!important}main.article-shell[data-article-template="unified-v1"]>.article .leadtext{font-size:20px!important}}
    `;
    document.head.appendChild(style);
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', install, {once:true});
  else install();
})();
